sl as (select o ord, case when o<=44 then ((o-1)/11)+1 else 5 end hari, case when o<=44 then ((o-1)%11)+1 else o-44 end jam from generate_series(1,48) o)
insert into public.kur_jadwal (rombel_id,semester_id,hari,jam_ke,mapel_id,ptk_id)
select r.id,'20261',sl.hari,sl.jam,mp2.id,p.id from x join sl on sl.ord=x.ord join mp on mp.c=x.m join gu on gu.c=x.g join public.rombel r on r.nama=x.r and r.jenis_rombel='Kelas Utama' and r.semester_id='20261' join public.kur_mapel mp2 on mp2.nama=mp.n join public.ptk p on lower(p.nama)=gu.n
where x.m<>''
on conflict (rombel_id,hari,jam_ke) do update set mapel_id=excluded.mapel_id, ptk_id=excluded.ptk_id, semester_id=excluded.semester_id;
select count(*) from public.kur_jadwal where mapel_id is not null;